# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::RelayOutboxSource do
  it "marking one generation sent by position leaves a later generation of the same entry unsent with only entry fields" do
    stamp = Time.utc(2026, 3, 2, 9)
    [[61, 1], [62, 2]].each do |position, version|
      OutboxSnapshot.create!(
        "outbox_position" => position, "id" => 6100, "project_id" => 3, "user_id" => 4, "agent_id" => nil,
        "work_date" => Date.new(2026, 3, 2), "duration" => 60.0, "note" => nil, "bill_status" => "unbilled",
        "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => stamp, "updated_at" => stamp, "company_id" => 1, "version" => version,
        "generation" => 1
      )
    end
    source = described_class.new

    source.mark_sent([61])
    rows = source.unsent_after(0, 10)

    expect(rows.map { |row| row.fetch("outbox_position") }).to eq([62])
    # "Payloads carry the full entry row with record ids, and no names, emails or tokens"
    expect(rows.first.fetch("entry").keys).to match_array(Timekeeping::OutboxFields::ENTRY_FIELDS)
    expect(rows.first.fetch("entry")).to include("id" => 6100, "version" => 2, "company_id" => 1)
  end
end
